li.OKResult:
	
local itemobj = story:GetBindThing()
local Ling = me.npcObj.LingV
	me:AddMsg("[NAME]输入法力成功。");
	itemobj:AddLing(Ling);
	me:AddPracticeResource("Ling",-Ling);

					
				world:SetRandomSeed(); 
				local itemobj = story:GetBindThing()
				local Ling = itemobj.LingV
				local nR = math.floor(1+(Ling/5000000))
				if Ling >= 5000000 then
				if Ling >= 30000000 and me:IsDisciple() == true then
				local nA = math.floor(1+(Ling/50000000))
				me:AddMsg("[NAME]激活了灵宝，领悟了上古神秘经文\n[color=#8A2BE2]法宝操控上限+1");
				me:ModifierProperty("NpcFight_FabaoNum",nA)
				itemobj:AddLing(-Ling);
				else
				for i = 1, nR do
				if me:IsDisciple() == true then
					nQ = {"Modifier_jineng_zhandou","Modifier_jineng_chushi","Modifier_jineng_yayi","Modifier_jineng_qigan","Modifier_jineng_lianqi","Modifier_jineng_liandan","Modifier_jineng_yuqi","Modifier_jineng_shufa","Modifier_jineng_huti"}
					nW = 
{"技能-战斗","技能-处世","技能-雅艺","技能-气感","技能-炼器","技能-炼丹","技能-御器","技能-术法","技能-护体"}	
					nE = me:RandomInt(1, #nW + 1)
				else
					nQ = {"Modifier_jineng_jinshi","Modifier_jineng_chushi","Modifier_jineng_zhandou","Modifier_jineng_gengzhong","Modifier_jineng_yayi","Modifier_jineng_qigan","Modifier_jineng_jianzhu","Modifier_jineng_pengren","Modifier_jineng_doufa","Modifier_jineng_lianqi","Modifier_jineng_liandan","Modifier_jineng_danqi"}
					nW = 
{"技能-金石","技能-处世","技能-战斗","技能-农耕","技能-雅艺","技能-气感","技能-版筑","技能-烹饪","技能-斗法","技能-巧匠","技能-岐黄","技能-丹器"}	
					nE = me:RandomInt(1, #nW + 1)
				end
				itemobj:AddLing(-Ling);
				me:AddMsg("[NAME]激活了灵宝，领悟了神秘经文,提升了[color=#8A2BE2]"..nW[nE].."[/color]等级上限。");
				me:AddModifier(nQ[nE]);
				end;
				end;


				else
				local nW = me:GetGLevel()
				itemobj:AddLing(-Ling);
				if me:IsDisciple() == true then
				local nQ = me:GetGElementKind()
					if nW >= 9 then
					miaoshu = "巨幅"
					elseif nW >= 5 then
					miaoshu = "大幅"
					else
					miaoshu = "中幅"
					end
					itemobj:AddLing(-Ling);
					me:LearnEsotericCustomize("灵宝秘术-",nQ,0,false,(0.15+0.2*nW),math.ceil((1+nW/3)*2),math.floor(1+nW/3),miaoshu)
				else
					me:AddMsg("领悟力不足，没有获得任何东西。");
				end;
				end;

li.NOResult:

	local itemobj = story:GetBindThing()
	local Ling = itemobj.LingV
	me:AddMsg("灵宝激活后灵气后继不足，无法继续激活。\n[color=#8A2BE2]激活失败，宝物灵气损失math.floor(Ling*0.3)点[/color]");
	itemobj:AddLing(-Ling*0.3);
